/* Presentation modes organize existing tools; they do not grant account permissions. */
(() => {
 const make=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
 const tabs=document.getElementById('tabs');
 const modes={personal:{label:'个人版',tabs:['overview','matching','rentVisuals','ledger','projects','map','events']},enterprise:{label:'企业版',tabs:['overview','profiles','matching','supply','workorders','rentVisuals','map','events']},government:{label:'政府板块',tabs:['overview','supply','profiles','workorders','rentVisuals','ledger','projects','scenario','map','events']}};
 const nav=make('nav');nav.id='housingModes';nav.setAttribute('aria-label','住房服务版本');tabs.before(nav);tabs.setAttribute('aria-label','住房功能');
 function activate(key,selectPage){const mode=modes[key]||modes.personal;document.documentElement.dataset.housingMode=key;
  for(const b of nav.children)b.setAttribute('aria-pressed',String(b.dataset.mode===key));
  for(const b of tabs.querySelectorAll('[data-tab]'))b.hidden=!mode.tabs.includes(b.dataset.tab);
  const current=tabs.querySelector('.active');if(selectPage&&(!current||current.hidden))tabs.querySelector('[data-tab="overview"]').click();
  try{localStorage.setItem('anke.rents.mode',key);}catch{}
 }
 for(const [key,mode] of Object.entries(modes)){const b=make('button',mode.label);b.type='button';b.dataset.mode=key;b.onclick=()=>activate(key,true);nav.append(b);}
 let stored='personal';try{const saved=localStorage.getItem('anke.rents.mode');if(modes[saved])stored=saved;}catch{}activate(stored,true);
 // Commands/deep links may open a feature belonging to another mode.
 tabs.addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b?.hidden){const key=Object.keys(modes).find(k=>modes[k].tabs.includes(b.dataset.tab));activate(key,false);}});
 // Keep the workspace focused on inputs and results.
 const units={market:'元/㎡/月',current:'元/㎡/月',area:'㎡',ratio:'%',cap:'%',income:'元/月',fee:'元/月'};
 for(const [id,unit] of Object.entries(units)){const input=document.getElementById(id);input.setAttribute('aria-describedby',id+'Unit');const hint=make('span',unit);hint.id=id+'Unit';hint.className='field-unit';input.after(hint);}
 const provenance=make('div');provenance.id='rentProvenance';provenance.setAttribute('aria-label','租金数据来源');document.querySelector('.filters').after(provenance);
 window.addEventListener('anke:rents-data',({detail:data})=>{provenance.replaceChildren();const badge=make('strong',data.dataset==='demo'?'演示数据 · 非真实房源':'导入样本');badge.className='source-badge';provenance.append(badge,make('span',document.getElementById('recordType').value+' · '+document.getElementById('lease').value+' · 元/㎡/月'));
  for(const source of data.sources||[]){const tag=make('span',(source.name||'来源待核实')+' · '+source.count+' 条');tag.className='source-badge';provenance.append(tag);}
  provenance.append(make('span','样本记录日期：'+(data.dateStart||'待核实')+' — '+(data.dateEnd||'待核实')));
 });
 window.dispatchEvent(new Event('anke:rents-ready'));
})();

